INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6313466, 932359, 86447, '<td valign="top">LOL at your comments, Karma.   And I love it that this did so well for you!</td>', 'LOL at your comments, Karma.   And I love it that this did so well for you!', '2011-02-14 15:58:53.000000', NULL, 0),
